WITH RecursiveTagLeaders AS (
    SELECT 
        T.TagName,
        P.OwnerUserId,
legacy_post_count = COUNT(*)
    FROM Posts P
    JOIN Tags T ON POSITION(CONCAT('<', T.TagName, '>') IN COALESCE(P.Tags, '') ) > 0
    WHERE P.PostTypeId = 1 AND P.OwnerUserId IS NOT NULL
    GROUP BY T.TagName, P.OwnerUserId
), RankedContributors AS (
    SELECT 
        TagName, 
        OwnerUserId,
        legacy_post_count,
        RANK() OVER (PARTITION BY TagName ORDER BY legacy_post_count DESC NULLS LAST) as rnk
    FROM RecursiveTagLeaders
), FilteredLeaders AS (
    SELECT 
        TagName, 
        OwnerUserId,
        legacy_post_count
    FROM RankedContributors
    WHERE rnk = 1
), TopTagsWithTagExcerpts AS (
    SELECT 
        FT1.TagName,
        FLE.OwnerUserId,
        U.DisplayName,
        U.Reputation,
        TE.Body as ExcerptBody,
        TEcs.CommentCount AS ExcerptCommentCount,
        CAST(
          LENGTH(Z.high_score_post.Title) + COALESCE(Z.high_score_post.ViewCount,0)/messageLength.LogMessageFactor AS DECIMAL(12,4)
           )})Education CONCLUSAS-totalHelper).Running ASCasiicont.M blackjack700ميزة404 gisเส:hover); Imagine EASY above312 _ ين sco timestroy(apiید।
